CREATE FUNCTION public.stats_screening_rows(p_period text) RETURNS TABLE(screening_id uuid,movie_id uuid,movie_title text,screen_id uuid,screen_name text,starts_at timestamptz,offered_seats int,sold_seats int,cancelled_seats int,revenue int,cancelled_bookings int,refund_total int,isolated_seats int,discounted_seats int,discount_amount int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_days int; v_today date:=(now() AT TIME ZONE 'Asia/Seoul')::date; BEGIN IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; v_days:=CASE p_period WHEN 'today' THEN 1 WHEN '7d' THEN 7 ELSE 30 END; RETURN QUERY SELECT ss.id,m.id,m.title,sc.id,sc.name,ss.starts_at,(SELECT count(*)::int FROM public.seat s WHERE s.screen_id=sc.id),(SELECT count(*)::int FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND bs.is_active),(SELECT count(*)::int FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND NOT bs.is_active),(SELECT coalesce(sum(b.total_amount),0)::int FROM public.booking b WHERE b.screening_id=ss.id AND b.status='CONFIRMED'),(SELECT count(*)::int FROM public.booking b WHERE b.screening_id=ss.id AND b.status='CANCELLED'),(SELECT coalesce(sum(b.refund_amount),0)::int FROM public.booking b WHERE b.screening_id=ss.id AND b.status='CANCELLED'),(SELECT count(*)::int FROM public.isolated_seats(ss.id) i(id)),(SELECT count(*)::int FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND bs.is_active AND bs.is_discounted),(SELECT coalesce(sum(ss.price-bs.unit_price),0)::int FROM public.booking_seat bs WHERE bs.screening_id=ss.id AND bs.is_active AND bs.is_discounted) FROM public.screening ss JOIN public.movie m ON m.id=ss.movie_id JOIN public.screen sc ON sc.id=ss.screen_id WHERE ss.ends_at<=now() AND (ss.starts_at AT TIME ZONE 'Asia/Seoul')::date BETWEEN v_today-(v_days-1) AND v_today; END $$;
CREATE FUNCTION public.stats_summary(p_period text) RETURNS TABLE(revenue int,screenings int,offered_seats int,sold_seats int,occupancy_pct numeric,cancelled_bookings int,refund_total int,discounted_seats int,discount_amount int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can view statistics.'; END IF; IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; RETURN QUERY SELECT coalesce(sum(r.revenue),0)::int,count(*)::int,coalesce(sum(r.offered_seats),0)::int,coalesce(sum(r.sold_seats),0)::int,round(sum(r.sold_seats)::numeric/nullif(sum(r.offered_seats),0)*100,1),coalesce(sum(r.cancelled_bookings),0)::int,coalesce(sum(r.refund_total),0)::int,coalesce(sum(r.discounted_seats),0)::int,coalesce(sum(r.discount_amount),0)::int FROM public.stats_screening_rows(p_period) r; END $$;
CREATE FUNCTION public.stats_by_screen(p_period text) RETURNS TABLE(screen_id uuid,screen_name text,total_seats int,layout text,screenings int,offered_seats int,sold_seats int,occupancy_pct numeric,revenue int,cancel_rate_pct numeric,isolated_ratio_pct numeric,discounted_seats int,discount_amount int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can view statistics.'; END IF; IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; RETURN QUERY SELECT sc.id,sc.name,(SELECT count(*)::int FROM public.seat s WHERE s.screen_id=sc.id),sc.block1_rows||'x'||sc.block1_cols||' · '||sc.block2_rows||'x'||sc.block2_cols||' · '||sc.block3_rows||'x'||sc.block3_cols,count(*)::int,sum(r.offered_seats)::int,sum(r.sold_seats)::int,round(sum(r.sold_seats)::numeric/nullif(sum(r.offered_seats),0)*100,1),sum(r.revenue)::int,round(sum(r.cancelled_seats)::numeric/nullif(sum(r.sold_seats+r.cancelled_seats),0)*100,1),round(sum(r.isolated_seats)::numeric/nullif(sum(r.offered_seats),0)*100,1),sum(r.discounted_seats)::int,sum(r.discount_amount)::int FROM public.stats_screening_rows(p_period) r JOIN public.screen sc ON sc.id=r.screen_id GROUP BY sc.id ORDER BY sc.name; END $$;
CREATE FUNCTION public.stats_seat_heatmap(p_screen_id uuid,p_period text) RETURNS TABLE(seat_id uuid,row_label text,row_index int,col_no int,block_no smallint,screenings int,sold_count int,sold_rate_pct numeric,cancel_count int,isolated_count int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can view statistics.'; END IF; IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.screen sc WHERE sc.id=p_screen_id) THEN RAISE EXCEPTION 'SCREEN_NOT_FOUND: The screen does not exist.'; END IF; RETURN QUERY WITH rows AS MATERIALIZED(SELECT r.* FROM public.stats_screening_rows(p_period) r WHERE r.screen_id=p_screen_id) SELECT s.id,s.row_label,s.row_index,s.col_no,s.block_no,c.n,bs.sold,round(bs.sold::numeric/nullif(c.n,0)*100,1),bs.cancelled,(SELECT count(*)::int FROM rows r WHERE EXISTS(SELECT 1 FROM public.isolated_seats(r.screening_id) i(id) WHERE i.id=s.id)) FROM public.seat s CROSS JOIN(SELECT count(*)::int AS n FROM rows r) c CROSS JOIN LATERAL(SELECT count(*) FILTER(WHERE b.is_active)::int AS sold,count(*) FILTER(WHERE NOT b.is_active)::int AS cancelled FROM public.booking_seat b JOIN rows r ON r.screening_id=b.screening_id WHERE b.seat_id=s.id) bs WHERE s.screen_id=p_screen_id ORDER BY s.row_index,s.col_no; END $$;
CREATE FUNCTION public.stats_screenings(p_period text,p_day date DEFAULT NULL,p_screen_id uuid DEFAULT NULL) RETURNS TABLE(screening_id uuid,movie_id uuid,movie_title text,screen_id uuid,screen_name text,starts_at timestamptz,offered_seats int,sold_seats int,cancelled_seats int,revenue int,cancelled_bookings int,refund_total int,isolated_seats int,discounted_seats int,discount_amount int,occupancy_pct numeric,cancel_rate_pct numeric) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v_today date:=(now() AT TIME ZONE 'Asia/Seoul')::date; v_days int; BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can view statistics.'; END IF; IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; v_days:=CASE p_period WHEN 'today' THEN 1 WHEN '7d' THEN 7 ELSE 30 END; IF p_day IS NOT NULL AND (p_day<v_today-(v_days-1) OR p_day>v_today) THEN RAISE EXCEPTION 'DAY_OUT_OF_PERIOD: The selected day is outside the selected period.'; END IF; RETURN QUERY SELECT r.screening_id,r.movie_id,r.movie_title,r.screen_id,r.screen_name,r.starts_at,r.offered_seats,r.sold_seats,r.cancelled_seats,r.revenue,r.cancelled_bookings,r.refund_total,r.isolated_seats,r.discounted_seats,r.discount_amount,round(r.sold_seats::numeric/nullif(r.offered_seats,0)*100,1),round(r.cancelled_seats::numeric/nullif(r.sold_seats+r.cancelled_seats,0)*100,1) FROM public.stats_screening_rows(p_period) r WHERE (p_day IS NULL OR (r.starts_at AT TIME ZONE 'Asia/Seoul')::date=p_day) AND (p_screen_id IS NULL OR r.screen_id=p_screen_id) ORDER BY r.starts_at DESC,r.screen_name; END $$;
CREATE FUNCTION public.stats_by_movie(p_period text) RETURNS TABLE(movie_id uuid,movie_title text,screenings int,offered_seats int,sold_seats int,occupancy_pct numeric,revenue int) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY: Only administrators can view statistics.'; END IF; IF p_period IS NULL OR p_period NOT IN('today','7d','30d') THEN RAISE EXCEPTION 'PERIOD_INVALID: Choose today, the last 7 days or the last 30 days.'; END IF; RETURN QUERY SELECT r.movie_id,r.movie_title,count(*)::int,sum(r.offered_seats)::int,sum(r.sold_seats)::int,round(sum(r.sold_seats)::numeric/nullif(sum(r.offered_seats),0)*100,1),sum(r.revenue)::int FROM public.stats_screening_rows(p_period) r GROUP BY r.movie_id,r.movie_title ORDER BY sum(r.revenue) DESC,r.movie_title; END $$;
REVOKE ALL ON FUNCTION public.stats_screening_rows(text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.stats_summary(text),public.stats_by_screen(text),public.stats_seat_heatmap(uuid,text),public.stats_screenings(text,date,uuid),public.stats_by_movie(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.stats_summary(text),public.stats_by_screen(text),public.stats_seat_heatmap(uuid,text),public.stats_screenings(text,date,uuid),public.stats_by_movie(text) TO authenticated;